using AfriWallet.Merchants.Settlement.Application.Abstractions;using AfriWallet.Merchants.Settlement.Domain.Settlements;namespace AfriWallet.Merchants.Settlement.Application.Policies;public sealed class MerchantSettlementRoutingPolicy{public void EnsureEligible(CaptureEligibleDecisionSnapshot d,MerchantSettlementRoute route){if(!string.Equals(d.DecisionType,"CaptureEligible",StringComparison.OrdinalIgnoreCase)||!string.Equals(d.DecisionStatus,"Approved",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Decision must be CaptureEligible and approved.");if(!string.Equals(d.MerchantRegistryStatus,"Active",StringComparison.OrdinalIgnoreCase)||!string.Equals(d.MerchantVerificationStatus,"Verified",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Merchant must be active and verified.");if(d.AmountMinor<=0)throw new InvalidOperationException("Amount must be positive.");if(route is not(MerchantSettlementRoute.MerchantSettlement or MerchantSettlementRoute.MerchantPayout))throw new InvalidOperationException("Unsupported settlement route.");}}public sealed class MerchantSettlementRetryPolicy{public const int MaxAttempts=3;public bool ShouldRetry(MerchantSettlementProviderStatus status,int attemptCount)=>attemptCount<MaxAttempts&&(status is MerchantSettlementProviderStatus.Timeout or MerchantSettlementProviderStatus.TemporaryFailure);}
